#include <bits/stdc++.h>
using namespace std;
int par[6002],rnk_[6002];
int find_(int x){return par[x]==x?x:par[x]=find_(par[x]);}
bool unite_(int a,int b){a=find_(a);b=find_(b);if(a==b)return false;if(rnk_[a]<rnk_[b])swap(a,b);par[b]=a;if(rnk_[a]==rnk_[b])rnk_[a]++;return true;}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N,K;
    cin>>N>>K;
    int tot=N+K;
    vector<int> id(tot);vector<double> x(tot),y(tot);vector<char> tp(tot);
    vector<int> robots,relays;
    for(int i=0;i<tot;i++){
        cin>>id[i]>>x[i]>>y[i]>>tp[i];
        if(tp[i]=='C') relays.push_back(i);
        else robots.push_back(i);
    }
    auto ecost=[&](int i,int j)->double{
        if(tp[i]=='C'&&tp[j]=='C') return 1e18;
        double dx=x[i]-x[j],dy=y[i]-y[j],D=dx*dx+dy*dy;
        if(tp[i]!='C'&&tp[j]!='C')
            if(tp[i]=='S'||tp[j]=='S') return 0.8*D;
        return D;
    };
    struct Edge{int u,v;double w;};
    vector<Edge> edges;
    for(int i=0;i<tot;i++)for(int j=i+1;j<tot;j++){
        if(tp[i]=='C'&&tp[j]=='C') continue;
        edges.push_back({i,j,ecost(i,j)});
    }
    sort(edges.begin(),edges.end(),[](auto&a,auto&b){return a.w<b.w;});
    for(int i=0;i<tot;i++){par[i]=i;rnk_[i]=0;}
    vector<Edge> tree;
    for(auto&e:edges){
        if(unite_(e.u,e.v)) tree.push_back(e);
    }
    bool changed=true;
    while(changed){
        changed=false;
        map<int,int> deg;
        for(auto&e:tree){deg[e.u]++;deg[e.v]++;}
        vector<Edge> nt;
        for(auto&e:tree){
            bool ru=(tp[e.u]=='C'&&deg[e.u]==1);
            bool rv=(tp[e.v]=='C'&&deg[e.v]==1);
            if(ru||rv){changed=true;continue;}
            nt.push_back(e);
        }
        tree=nt;
    }
    set<int> usedR;
    for(auto&e:tree){if(tp[e.u]=='C')usedR.insert(e.u);if(tp[e.v]=='C')usedR.insert(e.v);}
    if(usedR.empty()) cout<<"#";
    else{bool f=true;for(int c:usedR){if(!f)cout<<" ";cout<<id[c];f=false;}}
    cout<<"\n";
    {bool f=true;for(auto&e:tree){if(!f)cout<<" ";cout<<id[e.u]<<" "<<id[e.v];f=false;}cout<<"\n";}
}
